from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass
from math import hypot

from .tracking import TrackRecord


VRU_CLASSES = {"person", "bicycle", "motorcycle"}
VEHICLE_CLASSES = {"car", "bus", "truck"}


@dataclass
class RiskEvent:
    frame_idx: int
    actor_a: int
    actor_b: int
    actor_a_class: str
    actor_b_class: str
    risk_score: float
    risk_level: str
    confidence: float
    low_confidence: bool
    reason_codes: list[str]
    score_breakdown: dict[str, float]
    explanation: str


def _center_distance(a: TrackRecord, b: TrackRecord) -> float:
    ax, ay = a.center
    bx, by = b.center
    return hypot(ax - bx, ay - by)


def _box_overlap_ratio(a: TrackRecord, b: TrackRecord) -> float:
    x1 = max(a.x1, b.x1)
    y1 = max(a.y1, b.y1)
    x2 = min(a.x2, b.x2)
    y2 = min(a.y2, b.y2)
    overlap = max(0.0, x2 - x1) * max(0.0, y2 - y1)
    denom = max(a.area + b.area - overlap, 1.0)
    return overlap / denom


def _motion_delta(history: list[TrackRecord]) -> float:
    if len(history) < 2:
        return 0.0
    x0, y0 = history[0].center
    x1, y1 = history[-1].center
    return hypot(x1 - x0, y1 - y0)


def _history_strength(history: list[TrackRecord], min_history: int) -> float:
    if not history:
        return 0.0
    return min(1.0, len(history) / max(min_history, 1))


def score_conflicts(
    frame_tracks: list[TrackRecord],
    track_history: dict[int, list[TrackRecord]],
    cfg: dict,
) -> list[RiskEvent]:
    results: list[RiskEvent] = []
    for i, left in enumerate(frame_tracks):
        for right in frame_tracks[i + 1 :]:
            if left.cls_name == right.cls_name:
                continue
            if not (
                (left.cls_name in VRU_CLASSES and right.cls_name in VEHICLE_CLASSES)
                or (left.cls_name in VEHICLE_CLASSES and right.cls_name in VRU_CLASSES)
            ):
                continue

            distance = _center_distance(left, right)
            overlap = _box_overlap_ratio(left, right)
            motion = (
                _motion_delta(track_history[left.track_id][-cfg["horizon_frames"] :])
                + _motion_delta(track_history[right.track_id][-cfg["horizon_frames"] :])
            ) / 2.0
            history_score = min(
                _history_strength(track_history[left.track_id], cfg["min_history"]),
                _history_strength(track_history[right.track_id], cfg["min_history"]),
            )

            proximity_score = max(0.0, 1.0 - (distance / cfg["pair_distance_px"]))
            overlap_score = min(1.0, overlap * 4.0)
            motion_score = min(1.0, motion / cfg["motion_norm_px"])

            risk = (
                cfg["proximity_weight"] * proximity_score
                + cfg["overlap_weight"] * overlap_score
                + cfg["motion_weight"] * motion_score
                + cfg.get("history_weight", 0.0) * history_score
            )

            reason_codes: list[str] = []
            if proximity_score > 0.55:
                reason_codes.append("proximity_threshold_exceeded")
            if overlap_score > 0.20:
                reason_codes.append("crossing_path_overlap")
            if motion_score > 0.45:
                reason_codes.append("high_relative_motion")
            if history_score < 0.75:
                reason_codes.append("short_track_history")
            if not reason_codes:
                reason_codes.append("weak_conflict_signal")

            if risk >= cfg["high_threshold"]:
                level = "high"
            elif risk >= cfg["medium_threshold"]:
                level = "medium"
            else:
                level = "low"

            confidence = min(
                1.0,
                0.4 * max(left.confidence, right.confidence)
                + 0.4 * risk
                + 0.2 * history_score,
            )
            breakdown = {
                "proximity": round(proximity_score, 4),
                "overlap": round(overlap_score, 4),
                "motion": round(motion_score, 4),
                "history": round(history_score, 4),
            }
            explanation = (
                f"{level.capitalize()} risk: {left.cls_name} and {right.cls_name} show "
                f"close spacing and interaction cues."
            )
            results.append(
                RiskEvent(
                    frame_idx=left.frame_idx,
                    actor_a=left.track_id,
                    actor_b=right.track_id,
                    actor_a_class=left.cls_name,
                    actor_b_class=right.cls_name,
                    risk_score=round(risk, 4),
                    risk_level=level,
                    confidence=round(confidence, 4),
                    low_confidence=confidence < 0.45,
                    reason_codes=reason_codes,
                    score_breakdown=breakdown,
                    explanation=explanation,
                )
            )
    return results


def update_history(history: dict[int, list[TrackRecord]], tracks: list[TrackRecord]) -> None:
    for track in tracks:
        history[track.track_id].append(track)


def make_history_dict() -> dict[int, list[TrackRecord]]:
    return defaultdict(list)

